head.b:skin:
:root {
  --bg-canvas: #0d1117;
  --bg-surface: #161b22;
  --bg-inset: #010409;
  --border-default: #30363d;
  --text-primary: #e6edf3;
  --text-secondary: #8b949e;
  --accent-green: #3fb950;
  --accent-blue: #58a6ff;
  --accent-gold: #d29922;
  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  --font-mono: 'JetBrains Mono', monospace;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

body {
  background-color: var(--bg-canvas);
  color: var(--text-primary);
  font-family: var(--font-sans);
  line-height: 1.65;
  font-size: 16px;
  -webkit-font-smoothing: antialiased;
}

a { color: var(--accent-blue); text-decoration: none; }
a:hover { text-decoration: underline; }

/* Container */
.container {
  max-width: 860px;
  margin: 0 auto;
  padding: 0 20px;
}

/* Termux Top Bar */
.termux-header {
  background: var(--bg-inset);
  border-bottom: 1px solid var(--border-default);
  padding: 16px 0;
  position: sticky;
  top: 0;
  z-index: 100;
}

.header-inner {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
}

.brand-prompt {
  font-family: var(--font-mono);
  font-size: 1.05rem;
  font-weight: 700;
  color: var(--text-primary);
  display: flex;
  align-items: center;
  gap: 8px;
}

.prompt-symbol { color: var(--accent-green); }
.cursor {
  display: inline-block;
  width: 8px;
  height: 16px;
  background: var(--accent-green);
  animation: blink 1.1s infinite;
}
@keyframes blink { 0%, 49% { opacity: 1; } 50%, 100% { opacity: 0; } }

.status-badges {
  display: flex;
  gap: 8px;
  font-family: var(--font-mono);
  font-size: 0.75rem;
}

.badge {
  padding: 3px 8px;
  border-radius: 6px;
  border: 1px solid var(--border-default);
  background: var(--bg-surface);
  color: var(--text-secondary);
}

.badge-pass {
  border-color: rgba(63, 185, 80, 0.4);
  color: var(--accent-green);
  background: rgba(63, 185, 80, 0.1);
}

/* Hero / Bio Box (GitHub README style) */
.readme-box {
  background: var(--bg-surface);
  border: 1px solid var(--border-default);
  border-radius: 8px;
  margin: 28px 0;
  overflow: hidden;
}

.readme-header {
  background: var(--bg-inset);
  padding: 10px 16px;
  border-bottom: 1px solid var(--border-default);
  font-family: var(--font-mono);
  font-size: 0.85rem;
  color: var(--text-secondary);
  display: flex;
  justify-content: space-between;
}

.readme-body { padding: 20px; }
.readme-body h1 { font-size: 1.5rem; margin-bottom: 8px; }
.readme-body p { color: var(--text-secondary); font-size: 0.95rem; }

/* Post Cards */
.post-card {
  background: var(--bg-surface);
  border: 1px solid var(--border-default);
  border-radius: 8px;
  padding: 24px;
  margin-bottom: 24px;
  transition: border-color 0.2s ease;
}

.post-card:hover { border-color: var(--accent-blue); }

.post-meta {
  font-family: var(--font-mono);
  font-size: 0.8rem;
  color: var(--text-secondary);
  margin-bottom: 10px;
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}

.post-title {
  font-size: 1.45rem;
  font-weight: 700;
  margin-bottom: 14px;
  line-height: 1.3;
}

.post-title a { color: var(--text-primary); }
.post-title a:hover { color: var(--accent-blue); text-decoration: none; }

/* Google Answer Engine Quick-Summary Box */
.answer-box {
  background: var(--bg-inset);
  border-left: 3px solid var(--accent-green);
  padding: 14px 16px;
  margin: 16px 0;
  border-radius: 0 6px 6px 0;
  font-size: 0.95rem;
}

.answer-label {
  font-family: var(--font-mono);
  font-size: 0.75rem;
  text-transform: uppercase;
  color: var(--accent-green);
  font-weight: 700;
  display: block;
  margin-bottom: 4px;
}

/* Post Typography & Code Blocks */
.post-body h2, .post-body h3 {
  margin: 24px 0 12px;
  padding-bottom: 6px;
  border-bottom: 1px solid var(--border-default);
  font-weight: 600;
}

.post-body p { margin-bottom: 16px; }
.post-body ul, .post-body ol { margin: 0 0 16px 24px; }

.post-body pre {
  background: var(--bg-inset);
  border: 1px solid var(--border-default);
  border-radius: 6px;
  padding: 16px;
  overflow-x: auto;
  font-family: var(--font-mono);
  font-size: 0.88rem;
  color: var(--accent-green);
  margin: 16px 0;
}

.post-body code {
  font-family: var(--font-mono);
  background: rgba(110, 118, 129, 0.2);
  padding: 2px 6px;
  border-radius: 4px;
  font-size: 0.88em;
}

.post-body pre code { background: none; padding: 0; }

/* Pagination */
.blog-pager {
  display: flex;
  justify-content: space-between;
  margin: 32px 0;
  font-family: var(--font-mono);
  font-size: 0.9rem;
}

.pager-btn {
  background: var(--bg-surface);
  border: 1px solid var(--border-default);
  padding: 8px 16px;
  border-radius: 6px;
  color: var(--text-primary);
}

.pager-btn:hover {
  border-color: var(--accent-blue);
  text-decoration: none;
}

/* Footer */
.site-footer {
  border-top: 1px solid var(--border-default);
  padding: 28px 0;
  margin-top: 48px;
  text-align: center;
  font-family: var(--font-mono);
  font-size: 0.82rem;
  color: var(--text-secondary);
}
